import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor triplet_margin_loss_forward(torch::Tensor anchor,
                                           torch::Tensor positive,
                                           torch::Tensor negative,
                                           double margin);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
#include <type_traits>
using namespace cute;
template <typename T>
__global__ void triplet_margin_loss_kernel(
    const T* __restrict__ Aptr,
    const T* __restrict__ Pptr,
    const T* __restrict__ Nptr,
    float* __restrict__ loss_per_row,
    int D,
    float margin)
{
  const int row = blockIdx.x;
  const int tid = threadIdx.x;
  const int nthreads = blockDim.x;
  const T* a_row = Aptr + (size_t)row * D;
  const T* p_row = Pptr + (size_t)row * D;
  const T* n_row = Nptr + (size_t)row * D;
  float sum_pos = 0.0f;
  float sum_neg = 0.0f;
  // Vectorized path for float using float4 loads for coalesced, wide memory transactions.
  if constexpr (std::is_same<T, float>::value) {
    const int D4 = D / 4;
    const float4* a4 = reinterpret_cast<const float4*>(a_row);
    const float4* p4 = reinterpret_cast<const float4*>(p_row);
    const float4* n4 = reinterpret_cast<const float4*>(n_row);
    // Two independent accumulator chains per sum break the serial
    // add-dependency of the reduction loop, exposing more
    // instruction-level parallelism so the FMA units stay busier.
    float sum_pos0 = 0.0f, sum_pos1 = 0.0f;
    float sum_neg0 = 0.0f, sum_neg1 = 0.0f;
    #pragma unroll 4
    for (int i = tid; i < D4; i += nthreads) {
      float4 av = a4[i];
      float4 pv = p4[i];
      float4 nv = n4[i];
      float dpx = av.x - pv.x;
      float dpy = av.y - pv.y;
      float dpz = av.z - pv.z;
      float dpw = av.w - pv.w;
      float dnx = av.x - nv.x;
      float dny = av.y - nv.y;
      float dnz = av.z - nv.z;
      float dnw = av.w - nv.w;
      sum_pos0 += dpx * dpx + dpy * dpy;
      sum_pos1 += dpz * dpz + dpw * dpw;
      sum_neg0 += dnx * dnx + dny * dny;
      sum_neg1 += dnz * dnz + dnw * dnw;
    }
    sum_pos = sum_pos0 + sum_pos1;
    sum_neg = sum_neg0 + sum_neg1;
    // Handle tail elements not covered by vectorized loop
    for (int i = D4 * 4 + tid; i < D; i += nthreads) {
      float av = a_row[i];
      float pv = p_row[i];
      float nv = n_row[i];
      float dp = av - pv;
      float dn = av - nv;
      sum_pos += dp * dp;
      sum_neg += dn * dn;
    }
  } else {
    // Generic scalar path using CuTe tensors for non-float types
    auto gA = make_tensor(make_gmem_ptr(a_row), make_shape(D), make_stride(Int<1>{}));
    auto gP = make_tensor(make_gmem_ptr(p_row), make_shape(D), make_stride(Int<1>{}));
    auto gN = make_tensor(make_gmem_ptr(n_row), make_shape(D), make_stride(Int<1>{}));
    for (int i = tid; i < D; i += nthreads) {
      float av = static_cast<float>(gA(i));
      float pv = static_cast<float>(gP(i));
      float nv = static_cast<float>(gN(i));
      float dp = av - pv;
      float dn = av - nv;
      sum_pos += dp * dp;
      sum_neg += dn * dn;
    }
  }
  // Warp-level reduction using shuffle instructions, then combine partial sums across warps
  unsigned mask = 0xffffffffu;
  #pragma unroll
  for (int offset = 16; offset > 0; offset >>= 1) {
    sum_pos += __shfl_down_sync(mask, sum_pos, offset);
    sum_neg += __shfl_down_sync(mask, sum_neg, offset);
  }
  extern __shared__ float smem[];
  const int warp_id = tid >> 5;
  const int lane_id = tid & 31;
  const int num_warps = nthreads >> 5;
  float* shared_pos = smem;
  float* shared_neg = smem + num_warps;
  if (lane_id == 0) {
    shared_pos[warp_id] = sum_pos;
    shared_neg[warp_id] = sum_neg;
  }
  __syncthreads();
  if (warp_id == 0) {
    float p = (lane_id < num_warps) ? shared_pos[lane_id] : 0.0f;
    float n = (lane_id < num_warps) ? shared_neg[lane_id] : 0.0f;
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
      p += __shfl_down_sync(mask, p, offset);
      n += __shfl_down_sync(mask, n, offset);
    }
    if (lane_id == 0) {
      float dist_pos = sqrtf(p);
      float dist_neg = sqrtf(n);
      float loss = dist_pos - dist_neg + margin;
      loss = loss > 0.0f ? loss : 0.0f;
      // Write per-row loss directly instead of a global atomicAdd to avoid
      // heavy atomic contention across a very large number of blocks (rows).
      loss_per_row[row] = loss;
    }
  }
}
// Second-stage reduction kernel: sums the per-row losses using a small number
// of blocks (grid-stride loop) with block-level shared-memory + warp-shuffle
// reduction, followed by a single atomicAdd per block. This drastically
// reduces the number of atomic operations compared to one atomicAdd per row.
__global__ void reduce_sum_kernel(const float* __restrict__ in,
                                   float* __restrict__ out,
                                   int N)
{
  extern __shared__ float sdata[];
  const int tid = threadIdx.x;
  const int nthreads = blockDim.x;
  int idx = blockIdx.x * nthreads + tid;
  int stride = nthreads * gridDim.x;
  float sum = 0.0f;
  for (int i = idx; i < N; i += stride) {
    sum += in[i];
  }
  unsigned mask = 0xffffffffu;
  #pragma unroll
  for (int offset = 16; offset > 0; offset >>= 1) {
    sum += __shfl_down_sync(mask, sum, offset);
  }
  const int warp_id = tid >> 5;
  const int lane_id = tid & 31;
  const int num_warps = nthreads >> 5;
  if (lane_id == 0) {
    sdata[warp_id] = sum;
  }
  __syncthreads();
  if (warp_id == 0) {
    float v = (lane_id < num_warps) ? sdata[lane_id] : 0.0f;
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
      v += __shfl_down_sync(mask, v, offset);
    }
    if (lane_id == 0) {
      atomicAdd(out, v);
    }
  }
}
torch::Tensor triplet_margin_loss_forward(torch::Tensor anchor,
                                           torch::Tensor positive,
                                           torch::Tensor negative,
                                           double margin) {
  TORCH_CHECK(anchor.is_cuda() && positive.is_cuda() && negative.is_cuda(),
              "All inputs must be CUDA tensors");
  TORCH_CHECK(anchor.dim() == 2 && positive.dim() == 2 && negative.dim() == 2,
              "Inputs must be 2D tensors [N, D]");
  TORCH_CHECK(anchor.sizes() == positive.sizes() && anchor.sizes() == negative.sizes(),
              "anchor, positive, negative must have the same shape");
  auto a_c = anchor.contiguous();
  auto p_c = positive.contiguous();
  auto n_c = negative.contiguous();
  int64_t N = a_c.size(0);
  int64_t D = a_c.size(1);
  auto loss_per_row = torch::empty({N}, a_c.options().dtype(at::kFloat));
  auto loss_sum = torch::zeros({1}, a_c.options().dtype(at::kFloat));
  const int threads = 512;
  dim3 block(threads);
  dim3 grid((unsigned)N);
  size_t smem_bytes = 2 * (threads / 32) * sizeof(float);
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  AT_DISPATCH_FLOATING_TYPES(a_c.scalar_type(), "triplet_margin_loss_kernel", ([&] {
    triplet_margin_loss_kernel<scalar_t><<<grid, block, smem_bytes, stream>>>(
        a_c.data_ptr<scalar_t>(),
        p_c.data_ptr<scalar_t>(),
        n_c.data_ptr<scalar_t>(),
        loss_per_row.data_ptr<float>(),
        (int)D,
        (float)margin
    );
  }));
  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "triplet_margin_loss_kernel launch failed: ", cudaGetErrorString(err));
  const int reduce_threads = 256;
  int reduce_blocks = (int)((N + reduce_threads - 1) / reduce_threads);
  if (reduce_blocks > 108) reduce_blocks = 108;
  if (reduce_blocks < 1) reduce_blocks = 1;
  size_t reduce_smem_bytes = (reduce_threads / 32) * sizeof(float);
  reduce_sum_kernel<<<reduce_blocks, reduce_threads, reduce_smem_bytes, stream>>>(
      loss_per_row.data_ptr<float>(),
      loss_sum.data_ptr<float>(),
      (int)N
  );
  auto err2 = cudaGetLastError();
  TORCH_CHECK(err2 == cudaSuccess, "reduce_sum_kernel launch failed: ", cudaGetErrorString(err2));
  auto mean_loss = loss_sum / static_cast<double>(N);
  return mean_loss.squeeze();
}
"""

triplet_ext = load_inline(
    name="cute_triplet_margin_loss_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["triplet_margin_loss_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Computes Triplet Margin Loss using a custom CUTE/CUDA kernel.

    Parameters:
        margin (float): The margin between the positive and negative samples.
    """
    def __init__(self, margin=1.0):
        super(ModelNew, self).__init__()
        self.margin = float(margin)
        self._ext = triplet_ext

    def forward(self, anchor, positive, negative):
        return self._ext.triplet_margin_loss_forward(
            anchor, positive, negative, self.margin
        )

